            val = (-dist * 1000) - (prox * 10) - (1 if (nx + ny) < (sx + sy) else 0) * corner_bias

        # deterministic tie-breaker by lexicographic (dx,dy)
        if best_val is None or val > best_val or (val == best_val and (dx, dy) < best_move):
            best_val = val
            best_move = (dx, dy)

